            ["Enter to send · Shift+Enter for a new line · Escape to stop"] = ("Intro para enviar · Mayús+Intro para una nueva línea · Esc para detener", "Enter untuk mengirim · Shift+Enter untuk baris baru · Escape untuk berhenti"),
            ["Attach images, videos, PDFs and documents · or drop files / paste an image"] = ("Adjunta imágenes, vídeos, PDF y documentos · o arrastra archivos / pega una imagen", "Lampirkan gambar, video, PDF, dan dokumen · atau seret berkas / tempel gambar"),
