            ["Open Settings > Application to install and restart when ready."] = ("Abre Ajustes > Aplicación para instalar y reiniciar cuando estés listo.", "Buka Pengaturan > Aplikasi untuk memasang dan memulai ulang saat siap."),
            ["Available:"] = ("Disponible:", "Tersedia:"),
            ["Installed:"] = ("Instalado:", "Terpasang:"),
            ["Download updates automatically"] = ("Descargar actualizaciones automáticamente", "Unduh pembaruan otomatis"),
            ["Check for a release, download it, then choose when to install and restart."] = ("Busca una versión, descárgala y elige cuándo instalar y reiniciar.", "Periksa rilis, unduh, lalu pilih kapan memasang dan memulai ulang."),
            ["Check once at normal startup when the last attempt was at least 24 hours ago."] = ("Comprueba al iniciar si han pasado al menos 24 horas desde el último intento.", "Periksa saat mulai jika upaya terakhir setidaknya 24 jam yang lalu."),
            ["Automatic downloads are optional and may use a metered connection. They follow automatic startup checks; installation always waits for you."] = ("Las descargas automáticas son opcionales y pueden usar una conexión medida. Siguen las comprobaciones al inicio; la instalación siempre espera tu decisión.", "Unduhan otomatis opsional dan dapat memakai koneksi berbayar. Unduhan mengikuti pemeriksaan saat mulai; pemasangan selalu menunggu Anda."),
            ["Restore the previous app and its saved settings? Changes to settings and JSON profile data since that backup will be replaced. Local media files are kept."] = ("¿Restaurar la aplicación anterior y sus ajustes? Se reemplazarán los cambios de ajustes y perfiles JSON desde esa copia. Se conservarán los archivos multimedia locales.", "Pulihkan aplikasi sebelumnya dan pengaturan tersimpan? Perubahan pengaturan dan data profil JSON sejak cadangan akan diganti. Berkas media lokal dipertahankan."),
            ["Restore previous version"] = ("Restaurar versión anterior", "Pulihkan versi sebelumnya"),
            ["Download the official setup for this app's architecture and verify its size, version and SHA-256."] = ("Descarga el instalador oficial para esta arquitectura y verifica su tamaño, versión y SHA-256.", "Unduh pemasang resmi untuk arsitektur aplikasi ini dan verifikasi ukuran, versi, serta SHA-256."),
            ["Save, create a recovery copy, install the verified update and reopen NabyScape."] = ("Guarda, crea una copia de recuperación, instala la actualización verificada y vuelve a abrir NabyScape.", "Simpan, buat salinan pemulihan, pasang pembaruan terverifikasi, dan buka kembali NabyScape."),
            ["Downloads use official GitHub releases. SHA-256 checks integrity; unsigned checksums do not establish publisher identity. Windows security checks remain enabled."] = ("Las descargas usan versiones oficiales de GitHub. SHA-256 comprueba la integridad; las sumas sin firma no acreditan al editor. Los controles de seguridad de Windows siguen activos.", "Unduhan memakai rilis GitHub resmi. SHA-256 memeriksa integritas; checksum tanpa tanda tangan tidak membuktikan identitas penerbit. Pemeriksaan keamanan Windows tetap aktif."),
            ["Checks run only when you request them. A chat check sends one short message and may use provider credits; Hermes processes it as an agent message. Setup never opens the microphone or downloads models automatically."] = ("Las comprobaciones se ejecutan solo cuando las solicitas. Comprobar el chat envía un mensaje breve y puede usar créditos; Hermes lo procesa como mensaje de agente. La configuración nunca abre el micrófono ni descarga modelos automáticamente.", "Pemeriksaan hanya berjalan saat diminta. Pemeriksaan obrolan mengirim satu pesan singkat dan dapat memakai kredit penyedia; Hermes memprosesnya sebagai pesan agen. Penyiapan tidak pernah membuka mikrofon atau mengunduh model otomatis."),
        };
